#include <bits/stdc++.h>
using namespace std;using U=uint64_t;using I=uint32_t; constexpr int N=35,F=4096,M=4095,Q=851,FLAG=49140,HM=49141;
int ex[2*M],lg[F];int mul(int a,int b){return a&&b?ex[lg[a]+lg[b]]:0;}int inv(int a){assert(a);return ex[M-lg[a]];}int power(int a,int i){return a?ex[(lg[a]*i)%M]:!i;}
struct G{int t,a=-1,b=-1,c=-1;I m=0,k=0;};
struct W{vector<uint8_t> c[10];map<int,U> counts;U cc=0;void push(int j,I x){auto p=(uint8_t*)&x;c[j].insert(c[j].end(),p,p+4);}void add(G g){c[1].push_back(g.t);counts[g.t]++;int ar=(g.t>>4)&3;switch(ar){case 1:push(7,g.a);break;case 2:push(5,g.a);push(6,g.b);break;case 3:push(2,g.a);push(3,g.b);push(4,g.c);cc++;break;}if(g.t&64)push(8,g.m);if(g.t&128)push(9,g.k);}void cx(int a,int b){assert(a!=b);add({33,a,b});}void x(int a){add({17,a});}void sw(int a,int b){if(a!=b)add({34,a,b});}void fieldadd(int s,int dst,int v){if(!v)return;
 static vector<pair<int,int>> prep[F];static array<int,12> row[F];static bool done[F]{};
 if(!done[v]){done[v]=true;for(int a=0;a<12;a++){int z=mul(1<<a,v);for(int b=0;b<12;b++)if(z>>b&1)row[v][b]|=1<<a;}
 for(;;){int gain=0,bi=-1,bj=-1;for(int i=0;i<12;i++)for(int j=0;j<12;j++)if(i!=j){int g=-2;for(auto r:row[v])if(r>>j&1)g+=(r>>i&1)?1:-1;if(g>gain){gain=g;bi=i;bj=j;}}if(!gain)break;prep[v].push_back({bi,bj});for(int&r:row[v])if(r>>bj&1)r^=1<<bi;}}
 for(auto [a,b]:prep[v])cx(s+a,s+b);for(int b=0;b<12;b++)for(int a=0;a<12;a++)if(row[v][b]>>a&1)cx(s+a,dst+b);for(auto it=prep[v].rbegin();it!=prep[v].rend();++it)cx(s+it->first,s+it->second); }void constant(int dst,int v){for(int b=0;b<12;b++)if(v>>b&1)x(dst+b);}void scale(int q,int v){if(v==1)return;assert(v);int rows[12]={};for(int i=0;i<12;i++){int z=mul(1<<i,v);for(int j=0;j<12;j++)if(z>>j&1)rows[j]|=1<<i;}vector<G> g;for(int j=0;j<12;j++){int r=j;while(r<12&&!(rows[r]>>j&1))r++;assert(r<12);if(r!=j){swap(rows[r],rows[j]);g.push_back({34,q+r,q+j});}for(int i=0;i<12;i++)if(i!=j&&(rows[i]>>j&1)){rows[i]^=rows[j];g.push_back({33,q+j,q+i});}}for(int i=0;i<12;i++)assert(rows[i]==1<<i);for(auto it=g.rbegin();it!=g.rend();it++)add(*it);}
 void save(string name){ofstream f(name,ios::binary);unsigned char magic[]={0xd7,0x50,0xc7,0xd5,0xc3,0x29,0xd3,0x26,0xe3,0xcc,0x9f,0x68,0x34,0xf2,0xb8,0xbf};f.write((char*)magic,16);I h[4]={2,Q,HM+1,2*N+M};f.write((char*)h,16);U hs[]={c[1].size(),cc,c[5].size()/4,c[7].size()/4,c[8].size()/4,c[9].size()/4,0,0,0};f.write((char*)hs,72);auto reg=[&](string name,int start,bool qu){U kind=0,size=8+name.size()+48;I n=name.size(),r=12;f.write((char*)&kind,8);f.write((char*)&size,8);f.write((char*)&n,4);f.write((char*)&r,4);f.write(name.data(),n);for(int j=0;j<12;j++){I w=start+j;if(qu)w|=0x80000000;f.write((char*)&w,4);}};for(int i=0;i<N;i++)reg("P"+to_string(i),i*12,true);for(int i=0;i<N;i++)reg("V"+to_string(i),420+i*12,true);for(int i=0;i<M;i++)reg("E"+to_string(i),i*12,false);for(U k=1;k<=9;k++){U n=c[k].size();f.write((char*)&k,8);f.write((char*)&n,8);f.write((char*)c[k].data(),n);}cout<<name<<" Q="<<Q<<" paid="<<cc<<" ops="<<c[1].size()<<" CX="<<counts[33]<<" SWAP="<<counts[34]<<" HMR="<<counts[80]<<endl;}
};
W w;int betav[12],basis[12],B[36][36],S[12][4096],nleaves=0;
void leaf(int x){if(!x)return;int j=lg[x];nleaves++;
 w.add({64,-1,-1,-1,FLAG});for(int b=0;b<12;b++)w.add({193,-1,-1,-1,FLAG,I(12*j+b)});w.add({129,-1,-1,-1,0,FLAG});
 w.add({49,0,1,840});for(int b=2;b<12;b++)w.add({49,838+b,b,839+b});
 for(int b=0;b<12;b++)w.add({160,850,420+b,-1,0,I(j*12+b)});
 for(int b=11;b>=2;b--){w.add({80,839+b,-1,-1,HM});w.add({160,838+b,b,-1,0,HM});}
 w.add({80,840,-1,-1,HM});w.add({160,0,1,-1,0,HM});w.add({1});w.add({64,-1,-1,-1,FLAG});
}
void basischange(bool reverse){if(!reverse){for(int i=N;i>=0;i--){int a=inv(B[i][i]);if(i<N){w.scale(12*i,a);w.scale(420+12*i,a);}for(int j=0;j<i;j++)if(B[i][j]){if(i==N)w.constant(12*j,mul(a,B[i][j]));else{w.fieldadd(12*i,12*j,B[i][j]);w.fieldadd(420+12*i,420+12*j,B[i][j]);}}}}else{for(int i=0;i<=N;i++){int a=inv(B[i][i]);for(int j=i-1;j>=0;j--)if(B[i][j]){if(i==N)w.constant(12*j,mul(a,B[i][j]));else{w.fieldadd(12*i,12*j,B[i][j]);w.fieldadd(420+12*i,420+12*j,B[i][j]);}}if(i<N){w.scale(12*i,B[i][i]);w.scale(420+12*i,B[i][i]);}}}}
void split_update(int k,int c){if(!c)return;int h=1<<(k-1);for(int i=0;i<h&&i+h<=N;i++){int j=i+h;if(j==N)w.constant(12*i,mul(c,inv(B[N][N])));else{w.fieldadd(12*j,12*i,c);w.fieldadd(420+12*j,420+12*i,c);}}}
void dfs(int k,int a){if(k==0){leaf(a);return;}int c=S[k-1][a];split_update(k,c);dfs(k-1,a);split_update(k,1);dfs(k-1,a^betav[k-1]);split_update(k,c^1);}
void rolling(){for(int i=0;i<12;i++)w.x(i);for(int j=0;j<M;j++){int x=ex[j];for(int i=1;i<N;i++)for(int b=0;b<12;b++){w.cx(i*12+b,b);w.cx(420+i*12+b,420+b);}w.constant(0,power(x,N));leaf(x);w.constant(0,power(x,N));for(int i=N-1;i>0;i--)for(int b=0;b<12;b++){w.cx(420+i*12+b,420+b);w.cx(i*12+b,b);}for(int i=1;i<N;i++){w.scale(12*i,ex[i]);w.scale(420+12*i,ex[i]);}}for(int i=0;i<12;i++)w.x(i);}
int main(int argc,char**argv){int x=1;for(int i=0;i<M;i++){ex[i]=ex[i+M]=x;lg[x]=i;x<<=1;if(x&F)x^=0x1053;}assert(x==1);if(string(argv[1])=="rolling")rolling();else{ifstream f("plan.txt");for(int&i:betav)f>>i;for(int i=0;i<12;i++){f>>basis[i];assert(basis[i]==(1<<i));}for(int i=0;i<=N;i++)for(int j=0;j<=i;j++)f>>B[i][j];for(auto&row:S)for(int&i:row)f>>i;assert(f);basischange(false);for(int i=0;i<12;i++)w.x(i);dfs(12,0);for(int i=0;i<12;i++)w.x(i);basischange(true);}assert(nleaves==M);w.save(argv[2]);}
